function useDemoRequest() {
  const [request, setRequest] = useState<DemoRequest>(() => {
    try { return JSON.parse(localStorage.getItem('plateletlink-demo-request') || 'null') || defaultRequest; } catch { return defaultRequest; }
  });
  useEffect(() => { localStorage.setItem('plateletlink-demo-request', JSON.stringify(request)); }, [request]);
  return [request, setRequest] as const;
}

